<?php require 'config.php';auth();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$id=(int)($_POST['id']??0);$v=[trim($_POST['name']??''),($_POST['client_id']??'')?:null,trim($_POST['description']??''),$_POST['status']??'Planning',($_POST['budget']??'')!==''?$_POST['budget']:null,($_POST['start_date']??'')?:null,($_POST['end_date']??'')?:null];try{if(!$v[0])throw new RuntimeException('Project name is required.');if(!in_array($v[3],['Planning','In Progress','On Hold','Completed','Cancelled'],true))throw new RuntimeException('Invalid status.');if($id){$s=$p->prepare('UPDATE projects SET name=?,client_id=?,description=?,status=?,budget=?,start_date=?,end_date=? WHERE id=?');$s->execute([...$v,$id]);flash('Project updated.');}else{$s=$p->prepare('INSERT INTO projects(name,client_id,description,status,budget,start_date,end_date) VALUES(?,?,?,?,?,?,?)');$s->execute($v);flash('Project added.');}}catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'Could not save project. Check the selected client and dates.','error');}header('Location: projects.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=$p->prepare('SELECT * FROM projects WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$clients=$p->query('SELECT id,name FROM clients ORDER BY name')->fetchAll();$q='%'.trim($_GET['q']??'').'%';$s=$p->prepare('SELECT p.*,c.name client FROM projects p LEFT JOIN clients c ON c.id=p.client_id WHERE p.name LIKE ? OR c.name LIKE ? ORDER BY p.created_at DESC');$s->execute([$q,$q]);$rows=$s->fetchAll();$page='Projects';require 'includes/header.php';?><div class="heading"><div><p class="eyebrow">DELIVERY TRACKING</p><h1>Projects</h1><p class="muted">Manage project status, budget, and client assignment.</p></div></div><section class="panel form-panel"><div class="panel-head"><div><h2><?=$edit?'Edit project':'Add a project'?></h2><p>Associate work with a client if needed.</p></div></div><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Project name *<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Client<select name="client_id"><option value="">No client assigned</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>" <?=((string)($edit['client_id']??'')===(string)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['Planning','In Progress','On Hold','Completed','Cancelled'] as $st):?><option <?=($edit['status']??'Planning')===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Budget (NGN)<input type="number" min="0" step="0.01" name="budget" value="<?=e($edit['budget']??'')?>"></label><label>Start date<input type="date" name="start_date" value="<?=e($edit['start_date']??'')?>"></label><label>End date<input type="date" name="end_date" value="<?=e($edit['end_date']??'')?>"></label><label class="wide">Description<textarea name="description" rows="2"><?=e($edit['description']??'')?></textarea></label><div class="wide form-actions"><button class="btn primary"><?=$edit?'Save changes':'Add project'?></button><?php if($edit):?><a class="btn" href="projects.php">Cancel</a><?php endif;?></div></form></section><section class="panel listing"><div class="panel-head"><h2>Project list <small><?=count($rows)?></small></h2><form class="search"><input name="q" placeholder="Search projects..." value="<?=e($_GET['q']??'')?>"><button class="btn">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Status</th><th>Budget</th><th>Dates</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><small>#PRJ-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></small></td><td><?=e($r['client']??'—')?></td><td><span class="pill"><?=e($r['status'])?></span></td><td><?=$r['budget']!==null?'₦'.number_format((float)$r['budget'],2):'—'?></td><td><?=e($r['start_date']?:'—')?> <small>to <?=e($r['end_date']?:'—')?></small></td><td><a href="?edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'includes/footer.php';?>
